/* Trabajo Cerca: UX mobile first — overlay aislado basado en snapshot 1794590590707.
   No modifica backend, motores ni campaña/ubicación publicitaria. */
/* Tipografía y hero de escritorio más compacto sin ocultar contenido. */
@media (min-width:768px) {
  .tcStitchShell .neoHero { padding-block:24px; }
  .tcStitchShell .neoHero h1 { font-size:clamp(30px,3vw,36px);line-height:1.14;max-width:660px;margin:8px 0; }
  .tcStitchShell .neoHeroLead { font-size:14px;line-height:21px;max-width:650px;margin:5px 0 0; }
  .tcStitchShell .tcStitchHeroRadar { width:240px;height:240px;top:-26px;right:max(18px,calc((100vw - 1160px)/2));opacity:.06; }
  .tcStitchShell .neoSearchDock { margin-top:13px;padding:10px;gap:8px; }
  .tcStitchShell .neoSearchDock>label,.tcStitchShell .neoSearchDock>button { min-height:44px; }
  .tcStitchShell .neoSearchDock>button { font-size:14px;line-height:20px; }
  .tcStitchShell .neoDiscover { padding-top:18px; }
}
/* En móvil, portada centrada en empleo: cuatro destinos abajo, comuna arriba.
   Mantener cada slot de publicidad, incluido su fallback institucional. */
@media (max-width:767px) {
  .tcStitchShell .tcTopbarInner { padding-inline:8px!important;gap:5px!important; }
  .tcStitchShell .tcMobilePlace { display:flex!important;flex:0 1 97px!important;max-width:97px!important;min-width:68px!important;padding:4px 5px!important;margin-left:auto!important; }
  .tcStitchShell .tcMobilePlace select {font-size:11px!important;}
  .tcStitchShell .tcSiteMenu>summary {min-width:44px!important;width:44px!important;height:44px!important;min-height:44px!important;}
  .tcStitchShell .tcPurposeGateway,.tcStitchShell .tcStitchRadarSummary {display:none!important;}
  .tcStitchShell .neoDiscover {padding:4px 12px 0!important;}
  .tcStitchShell .neoDiscoverHead {margin:2px 0 8px!important;}
  .tcStitchShell .tcInlineHousePromo[data-placement='search'] {grid-template-columns:minmax(0,1fr) auto;gap:8px;width:calc(100% - 24px);margin:6px auto;padding:8px 10px;min-height:58px;}
  .tcStitchShell .tcInlineHousePromo[data-placement='search'] .tcInlineHouseIcon,
  .tcStitchShell .tcInlineHousePromo[data-placement='search'] .tcInlineHouseCopy small,
  .tcStitchShell .tcInlineHousePromo[data-placement='search'] .tcInlineHouseCopy p {display:none;}
  .tcStitchShell .tcInlineHousePromo[data-placement='search'] .tcInlineHouseCopy strong {font-size:12px;line-height:16px;}
  .tcStitchShell .tcInlineHousePromo[data-placement='search'] button {grid-column:2;min-height:44px;padding:6px 9px;font-size:11px;}
  .tcStitchShell .neoMobileNav {grid-template-columns:repeat(4,minmax(0,1fr));height:calc(60px + env(safe-area-inset-bottom));min-height:60px;}
  .tcStitchShell .neoMobileNav button {min-width:0;min-height:44px;font-size:11px;gap:3px;}
  .tcStitchShell .neoMobileNav button[aria-current='page'] {color:#1b4332;font-weight:700;}
  .tcStitchShell .neoMobileNav button:first-child:not([aria-current='page']) {color:var(--st-muted);font-weight:500;}
  .tcStitchShell .tcMobilePublishAction {position:fixed;right:12px;bottom:calc(66px + env(safe-area-inset-bottom));z-index:69;display:inline-flex;align-items:center;gap:5px;min-height:44px;padding:8px 12px;background:#1b4332;color:white;border:1px solid #cad8ce;border-radius:24px;font-size:12px;font-weight:700;box-shadow:0 2px 12px #10352929;}
  .tcStitchShell .tcMobilePublishAction svg {width:16px;height:16px;}
  .tcStitchShell .neoJobCard h3 {font-size:14px!important;line-height:19px!important;-webkit-line-clamp:2!important;}
}
@media(min-width:768px) {.tcStitchShell .tcMobilePublishAction {display:none;}}
.tcStitchShell .tcPublishBackdrop {position:fixed;inset:0;z-index:120;display:grid;place-items:center;padding:16px;background:#071c15b8;}
.tcStitchShell .tcPublishDialog {width:min(100%,480px);max-height:calc(100dvh - 32px);overflow:auto;border:1px solid #cad8ce;border-radius:16px;background:#fff;color:#16211c;padding:16px;box-shadow:0 18px 48px #071c1560;}
.tcStitchShell .tcPublishDialogHeader {display:flex;justify-content:space-between;align-items:center;gap:12px;}
.tcStitchShell .tcPublishDialogHeader h2 {margin:0;font-size:20px;line-height:26px;}
.tcStitchShell .tcPublishDialogHeader>button {width:44px;height:44px;border:0;background:#edf4ef;border-radius:10px;display:grid;place-items:center;}
.tcStitchShell .tcPublishDialog>p {margin:8px 0 12px;font-size:13px;line-height:19px;color:#475850;}
.tcStitchShell .tcPublishDialog>button {display:flex;align-items:center;gap:12px;text-align:left;width:100%;min-height:64px;margin-top:7px;padding:10px;border:1px solid #d5e0da;border-radius:12px;background:#f9fbfa;color:#16211c;}
.tcStitchShell .tcPublishDialog>button>svg {width:20px;height:20px;color:#2d6a4f;}
.tcStitchShell .tcPublishDialog>button>span {min-width:0;display:flex;flex-direction:column;gap:4px;}
.tcStitchShell .tcPublishDialog strong {font-size:14px;line-height:19px;}
.tcStitchShell .tcPublishDialog small {font-size:12px;line-height:17px;color:#475850;}
.tcStitchShell .tcPublishDialog:focus-visible {outline:3px solid #2d6a4f;outline-offset:3px;}
@media(prefers-reduced-motion:reduce){
 .tcStitchShell .tcMobilePublishAction,.tcStitchShell .tcPublishDialog {animation:none!important;transition:none!important;}
}

/* La opción de consentimiento es global; nunca puede tapar navegación o el CTA. */
@media(max-width:767px){
 .tcStitchShell .tcAnalyticsChoice{
   position:fixed!important;left:10px!important;right:10px!important;
   bottom:calc(122px + env(safe-area-inset-bottom))!important;
   width:auto!important;max-width:420px!important;
   padding:10px!important;gap:8px!important;
   z-index:80!important;
 }
 .tcStitchShell .tcAnalyticsChoice span{flex:1 1 100%!important;font-size:12px;line-height:17px;}
 .tcStitchShell .tcAnalyticsChoice button{min-height:44px;padding:8px 10px;font-size:12px;flex:1 1 110px;}
}

/* RC9 mobile: readable communes, unclipped paid ad, discreet PWA install invitation. */
/* All overrides are confined to presentation; paid placement allocation unchanged. */
.tcStitchShell .tcInstallInvite{
 width:min(1180px,calc(100% - 24px));margin:9px auto 4px;
 display:grid;grid-template-columns:35px minmax(0,1fr) auto 30px;
 align-items:center;gap:10px;padding:9px 11px;
 background:#edf6eb;color:#214b34;border:1px solid #cfe4ce;border-radius:12px;
 box-sizing:border-box;min-width:0;box-shadow:0 2px 8px #143e2510;
}
.tcStitchShell .tcInstallInvite>img{width:35px;height:35px;object-fit:contain;flex:none}
.tcStitchShell .tcInstallInviteCopy{display:flex;flex-direction:column;gap:2px;min-width:0}
.tcStitchShell .tcInstallInviteCopy strong{font-size:12px;line-height:1.3;font-weight:800}
.tcStitchShell .tcInstallInviteCopy span{font-size:10px;line-height:1.45;color:#587361}
.tcStitchShell .tcInstallInvite button{
 display:inline-flex;align-items:center;justify-content:center;gap:6px;
 min-height:36px;min-width:0;border-radius:9px;border:1px solid #b3ceb8;
 font-size:11px;font-weight:800;white-space:nowrap;cursor:pointer}
.tcStitchShell .tcInstallInvite .tcInstallInviteAction{
 padding:8px 10px;color:#fff;background:#16553a;border-color:#16553a}
.tcStitchShell .tcInstallInvite .tcInstallInviteAction svg{width:15px;height:15px}
.tcStitchShell .tcInstallInvite .tcInstallInviteClose{
 width:29px;min-width:29px;min-height:32px;padding:6px;border:0;background:transparent;color:#476851}
.tcStitchShell .tcInstallInvite .tcInstallInviteClose svg{width:15px;height:15px}
.tcStitchShell .tcInstallInvite button:focus-visible,.tcStitchShell .tcShareInstallButton:focus-visible{
 outline:3px solid #7fac70;outline-offset:2px}
.tcStitchShell .tcShareInstallButton{
 display:flex!important;align-items:center!important;justify-content:center!important;
 gap:8px!important;width:100%;max-width:100%;min-height:44px!important;
 padding:11px 14px!important;border:1px solid #a5c4ac!important;
 border-radius:10px!important;background:#edf8ef!important;color:#175637!important;
 font-size:12px!important;font-weight:800!important;white-space:normal!important}
.tcStitchShell .tcShareInstallButton svg{width:16px;height:16px;flex:none}
/* A user explicitly opening Preferences can still opt in; default analytics is off. */
.tcStitchShell .tcAnalyticsChoice{max-width:calc(100vw - 24px);z-index:95}
.tcStitchShell .tcMobilePlaceLabel{font-size:10px;line-height:1.3;color:#51735c;font-weight:750;white-space:nowrap}
@media(max-width:767px){
 /* Reserve a complete second header row for the place name, including Nacimiento,
    Capitán Pastene or a long complement-city name at narrow widths. */
 .tcStitchShell{padding-top:100px!important}
 .tcStitchShell .neoTopbar{
   height:100px!important;min-height:100px!important;max-height:none!important;
   overflow:visible!important}
 .tcStitchShell .tcTopbarInner{
   display:grid!important;grid-template-columns:minmax(0,1fr) 42px!important;
   grid-template-rows:40px 39px!important;column-gap:8px!important;row-gap:5px!important;
   align-items:center!important;width:100%!important;min-width:0!important;
   height:100px!important;min-height:100px!important;max-height:none!important;
   padding:5px 12px!important;box-sizing:border-box!important}
 .tcStitchShell .neoTopbar .tcTopbarInner>.neoBrand{
   grid-column:1!important;grid-row:1!important;
   flex:none!important;width:100%!important;min-width:0!important;max-width:100%!important;
   justify-self:start!important;align-self:center!important}
 .tcStitchShell .neoTopbar .tcTopbarInner>.tcSiteMenu{
   grid-column:2!important;grid-row:1!important;
   justify-self:end!important;align-self:center!important;position:relative}
 .tcStitchShell .neoTopbar .tcTopbarInner>.tcMobilePlace{
   grid-column:1/-1!important;grid-row:2!important;display:flex!important;
   flex:none!important;width:100%!important;min-width:0!important;max-width:100%!important;
   height:39px!important;min-height:39px!important;max-height:39px!important;
   padding:5px 11px!important;gap:8px!important;border-radius:10px!important;
   justify-self:stretch!important;align-self:center!important;box-sizing:border-box!important}
 .tcStitchShell .tcMobilePlace select{
   display:block!important;flex:1 1 auto!important;width:100%!important;max-width:none!important;
   min-width:0!important;line-height:1.35!important;font-size:13px!important;font-weight:750!important;
   overflow:visible!important;text-overflow:clip!important;white-space:nowrap!important}
 .tcStitchShell .tcMobilePlace svg{width:16px!important;height:16px!important;flex:0 0 16px!important}
 /* Real paid advertisements: first row has visible image and copy; second row CTA.
    Explicit grid placements override legacy 64px and RC8 1-column declarations. */
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard{
   box-sizing:border-box!important;overflow:visible!important;min-width:0!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcAdContent.tcPremiumCommercial,
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcAdContent.tcPremiumCommercial[data-has-image=true]{
   display:grid!important;width:100%!important;max-width:100%!important;min-width:0!important;
   grid-template-columns:clamp(86px,26vw,108px) minmax(0,1fr)!important;
   grid-template-rows:auto auto!important;gap:9px 12px!important;
   align-items:center!important;overflow:visible!important;position:relative!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcAdContent.tcPremiumCommercial>.tcCommercialVisual,
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcAdContent.tcPremiumCommercial>.tcCommercialVisual:has(>.tcAdImage){
   grid-column:1!important;grid-row:1!important;
   width:100%!important;height:105px!important;min-height:105px!important;max-height:105px!important;
   min-width:0!important;position:relative!important;overflow:hidden!important;
   border-radius:11px!important;align-self:start!important;box-sizing:border-box!important;
   background:#edf5ed!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcCommercialVisual .tcCommercialSlides{
   display:block!important;position:relative!important;width:100%!important;height:100%!important;
   min-height:0!important;max-height:100%!important;border-radius:11px!important;overflow:hidden!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcCommercialSlides>img{
   position:absolute!important;inset:0!important;width:100%!important;height:100%!important;
   max-width:100%!important;max-height:100%!important;object-fit:contain!important;
   object-position:center!important;box-sizing:border-box!important;padding:3px!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcAdContent.tcPremiumCommercial>.tcCommercialCopy{
   grid-column:2!important;grid-row:1!important;display:flex!important;flex-direction:column!important;
   align-items:flex-start!important;justify-content:center!important;
   min-width:0!important;width:100%!important;max-width:100%!important;align-self:center!important;
   gap:4px!important;overflow:visible!important;box-sizing:border-box!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcCommercialCopy .tcCommercialKicker{
   max-width:100%!important;white-space:normal!important;overflow:visible!important;
   text-overflow:clip!important;line-height:1.35!important;font-size:9px!important;overflow-wrap:break-word!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcCommercialCopy .tcCommercialName{
   display:block!important;max-width:100%!important;overflow:visible!important;
   text-overflow:clip!important;white-space:normal!important;overflow-wrap:break-word!important;
   font-size:clamp(15px,3.9vw,18px)!important;line-height:1.2!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcCommercialCopy .tcCommercialHeadline{
   display:-webkit-box!important;-webkit-line-clamp:2!important;-webkit-box-orient:vertical!important;
   font-size:11px!important;line-height:1.35!important;max-width:100%!important;
   white-space:normal!important;overflow:hidden!important;overflow-wrap:break-word!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcAdContent.tcPremiumCommercial>.tcCommercialAction{
   grid-column:1/-1!important;grid-row:2!important;display:flex!important;
   justify-content:stretch!important;align-items:stretch!important;
   min-width:0!important;width:100%!important;max-width:100%!important;
   position:static!important;transform:none!important;align-self:stretch!important;
   margin:0!important;padding:0!important;overflow:visible!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcCommercialAction>a{
   box-sizing:border-box!important;display:inline-flex!important;justify-content:center!important;
   align-items:center!important;gap:8px!important;width:100%!important;max-width:100%!important;
   min-width:0!important;min-height:42px!important;padding:9px 12px!important;
   border-radius:9px!important;font-size:12px!important;line-height:1.4!important;
   overflow-wrap:break-word!important;text-align:center!important;white-space:normal!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcAdLabel{
   flex-wrap:wrap!important;align-items:center!important;max-width:100%!important}
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcAdLabel small{
   display:inline-block!important;max-width:100%!important;overflow:visible!important;
   text-overflow:clip!important;white-space:normal!important}
 .tcStitchShell .tcInstallInvite{grid-template-columns:32px minmax(0,1fr) 29px;gap:8px;padding:9px}
 .tcStitchShell .tcInstallInvite>img{width:32px;height:32px;grid-column:1;grid-row:1}
 .tcStitchShell .tcInstallInviteCopy{grid-column:2;grid-row:1}
 .tcStitchShell .tcInstallInviteAction{grid-column:2;grid-row:2;justify-self:start}
 .tcStitchShell .tcInstallInviteClose{grid-column:3;grid-row:1;align-self:start}
}
@media(max-width:355px){
 .tcStitchShell .tcMobilePlace select{font-size:12px!important}
 .tcStitchShell .tcCommercialCard .tcAdContent.tcPremiumCommercial,
 .tcStitchShell .tcLocalAdvertising.tcCommercialCard .tcAdContent.tcPremiumCommercial{
  gap:8px!important;grid-template-columns:86px minmax(0,1fr)!important}
}

/* RC10: Android native <select> text ellipsizes even in full-width row.
   Show the exact selected place as ordinary text; retain real native control. */
.tcStitchShell .tcMobilePlaceValue{display:none;pointer-events:none}
@media(max-width:767px){
  .tcStitchShell .neoTopbar .tcTopbarInner>.tcMobilePlace{
    position:relative!important;isolation:isolate!important;
    box-sizing:border-box!important;width:100%!important;max-width:none!important;
    grid-column:1/-1!important;grid-row:2!important;min-width:0!important;
    display:flex!important;justify-content:flex-start!important;
    align-items:center!important;padding-inline:12px 34px!important;
    overflow:hidden!important
  }
  .tcStitchShell .tcMobilePlace .tcMobilePlaceLabel{display:none!important}
  .tcStitchShell .tcMobilePlace .tcMobilePlaceValue{
    display:block!important;flex:1 1 auto!important;min-width:0!important;
    max-width:100%!important;white-space:normal!important;
    overflow-wrap:break-word!important;word-break:normal!important;
    font-size:clamp(12px,3.6vw,15px)!important;line-height:1.2!important;
    font-weight:750!important;color:#24573c!important;overflow:visible!important
  }
  .tcStitchShell .tcMobilePlace>select{
    display:block!important;position:absolute!important;inset:0!important;
    width:100%!important;height:100%!important;max-width:none!important;
    min-width:100%!important;margin:0!important;opacity:0!important;
    z-index:3!important;cursor:pointer!important;appearance:none!important
  }
  .tcStitchShell .tcMobilePlace:after{
    content:'⌄';position:absolute;right:12px;top:50%;
    transform:translateY(-55%);font-size:23px;line-height:1;
    color:#326b49;pointer-events:none;z-index:2
  }
  .tcStitchShell .tcMobilePlace:focus-within{
    outline:2px solid #338b5a!important;outline-offset:2px!important
  }
}

/* Trabajo Cerca UX consolidated overlay. SEO remains disabled in pilot. */
/* Reserve the line box for the catalogue status to avoid counter layout shifts. */
.tcStitchShell .tcCatalogCount { font-variant-numeric:tabular-nums; line-height:1.45; }
@media(prefers-reduced-motion:reduce){
  .tcStitchShell .neoJobCard { transition:none!important;animation:none!important; }
}
.tcStitchShell[data-directory-open='true']>.tcRadarCompactRegion{display:none!important}
.tcStitchShell .tcWebsiteNewsOnly{display:block!important}
.tcStitchShell .tcDirectoryIllustration{height:112px;background:#edf4ed;border-radius:11px;margin:0 0 9px;overflow:hidden}
.tcStitchShell .tcDirectoryIllustration img{width:100%;height:100%;object-fit:cover;opacity:.83}
.tcStitchShell .tcDirectoryMore,.tcStitchShell .tcRecoverDirectory{min-height:44px;border:1px solid #bed6c5;border-radius:10px;padding:10px 14px;background:#e8f3e8;color:#154832;margin:8px 0;font-weight:700;font-size:13px}
.tcStitchShell .tcAdPhotoNotice{font-size:12px;line-height:17px;color:#4e6657;margin:6px 0}
.tcStitchShell .tcAdSlotChoices{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;border:1px solid #cde2d2;padding:12px;border-radius:10px}
.tcStitchShell .tcAdSlotChoices label{display:flex;align-items:center;gap:8px;font-size:13px}
.tcStitchShell .tcAdSlotChoices input{width:18px;height:18px}
.tcStitchShell .tcAdPreviewToggle{min-height:44px;border:1px solid #cde2d2;background:#fff;padding:10px;border-radius:10px;font-weight:700}
.tcStitchShell .tcAdLeadPreview{display:grid;grid-template-columns:95px minmax(0,1fr);gap:11px;padding:10px;border-radius:10px;background:#edf6ed}
.tcStitchShell .tcAdLeadPreview img{width:95px;height:90px;object-fit:cover;border-radius:8px}
.tcStitchShell .tcAdLeadPreview div{display:grid;gap:5px}.tcStitchShell .tcAdLeadPreview p{margin:0}
@media(max-width:767px){
.tcStitchShell .tcInlineHousePromo:has(.tcHouseFallbackThumb){grid-template-columns:76px minmax(0,1fr)!important;grid-template-areas:"photo copy" "photo cta"!important;min-height:120px!important;gap:7px 10px!important}
.tcStitchShell .tcInlineHousePromo .tcInlineHouseCopy small{font-size:11px!important;line-height:14px!important}
.tcStitchShell .tcInlineHousePromo .tcInlineHouseCopy strong{font-size:15px!important;line-height:19px!important}
.tcStitchShell .tcInlineHousePromo .tcInlineHouseCopy p{font-size:12px!important;line-height:17px!important}
.tcStitchShell .tcInlineHousePromo>button,.tcStitchShell .tcFounderCard .tcFounderCta,.tcStitchShell .tcHouseAd.tcPremiumAd button{min-height:44px!important;font-size:12px!important;line-height:16px!important}
.tcStitchShell .tcAdSlotChoices{grid-template-columns:1fr}
}

/* Trabajo Cerca · compact presentation only. No catalog, filters, or backend changes. */
.tcStitchShell .tcWorkplaceLabel{
  display:block;min-width:0;max-width:100%;text-align:left;
  white-space:normal;word-break:normal;overflow-wrap:normal;
  line-height:1.25;
}
.tcStitchShell .neoJobPlace svg{flex:0 0 12px;}
.tcStitchShell .tcRadarCompactRegion{max-width:1012px;width:calc(100% - 32px);margin:14px auto 4px;}
.tcStitchShell .tcRadarCompactRegion>.tcTerritorialRadar{width:100%;max-width:100%;min-width:0;box-sizing:border-box;}
.tcStitchShell .tcRadarCompactRegion .tcRadarHeading{min-width:0;align-items:center;}
.tcStitchShell .tcRadarCompactRegion .tcRadarHeading>div{min-width:0;}
.tcStitchShell .tcRadarCompactRegion .tcRadarHeading h2{overflow-wrap:normal;}
.tcStitchShell .tcRadarCompactRegion .tcRadarDetails>summary{min-width:0;max-width:100%;box-sizing:border-box;white-space:normal;overflow-wrap:normal;}
.tcStitchShell .tcStitchFooterDetails{max-width:1012px;}
.tcStitchShell .tcCompactFooter{box-sizing:border-box;}
.tcStitchShell .tcCompactFooter .tcFooterLegal{flex-wrap:wrap;min-width:0;}
@media(max-width:767px){
  /* The visible tag contains only a locality, never an employer/operations description. */
  .tcStitchShell .neoJobTop{width:114px!important;max-width:114px!important;min-width:0!important;align-items:flex-end!important;gap:5px!important;}
  .tcStitchShell .neoJobPlace{
    display:flex!important;align-items:flex-start!important;
    width:auto!important;max-width:100%!important;min-width:0!important;
    box-sizing:border-box!important;padding:4px 6px!important;
    gap:4px!important;white-space:normal!important;word-break:normal!important;
    font-size:11px!important;line-height:14px!important;letter-spacing:0!important;
    border-radius:10px!important;overflow:hidden!important;
  }
  .tcStitchShell .tcWorkplaceLabel{
    display:-webkit-box!important;-webkit-box-orient:vertical!important;
    -webkit-line-clamp:2!important;overflow:hidden!important;
    font-size:11px!important;line-height:14px!important;
  }
