}.neoTopActions{display:flex;align-items:center;gap:8px}.neoPlace{display:flex;align-items:center;gap:5px;border:1px solid var(--neo-line);border-radius:999px;padding:8px 10px;background:#fff}.neoPlace svg{width:14px;color:var(--neo-coral)}.neoPlace select{border:0;background:transparent;outline:0;color:var(--neo-ink);font-size:10px;font-weight:700;max-width:120px}.neoCompare{border:1px solid var(--neo-line);background:transparent;color:#53665f;border-radius:999px;padding:9px 11px;font-size:9px;font-weight:700}.neoEyebrow,.neoKicker{display:inline-flex;align-items:center;gap:6px;font-size:8px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.neoEyebrow{background:var(--neo-ink);color:white;border-radius:999px;padding:8px 10px}.neoEyebrow svg{width:13px;color:var(--neo-lime)}

