spacing:.08em;text-transform:uppercase;color:#7b8a83}.neoFloatJob b{font-size:10px;line-height:1.25;margin-top:4px}.neoFloatJob small{font-size:7px;color:#6b7b74;margin-top:5px}.neoFloatJob0{left:7%;bottom:10%;transform:rotate(-2deg)}.neoFloatJob1{right:5%;top:8%;transform:rotate(2deg)}.neoFloatJob2{right:4%;bottom:8%;transform:rotate(-1deg)}.neoCanvasLabel{position:absolute;left:24px;top:22px;color:white;display:flex;flex-direction:column;z-index:5}.neoCanvasLabel span{font-size:7px;letter-spacing:.12em;font-weight:900;color:var(--neo-lime)}.neoCanvasLabel b{font-size:13px;margin-top:3px}
